<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import SchematicMap from './components/SchematicMap.vue'
import ForecastChart from './components/ForecastChart.vue'
import RegistryForm from './components/RegistryForm.vue'
import ResearchAssessment from './components/ResearchAssessment.vue'

import { ApiClient, createKey } from './lib/api'
import { forecastQuery, formatTime, importFormat, localized, selectedSeries, formatNumber, observationTimeUTC, sourceSummary } from './lib/presentation'
import type { RegistryKind } from './lib/registryForms'

type Page = 'map'|'assets'|'forecast'|'observations'|'sources'|'validation'

const page=ref<Page>('map'), data=ref<any>(null), busy=ref(false), error=ref(''), notice=ref(''), drawer=ref(false), query=ref(''), condition=ref('all')
const selectedId=ref(''), date=ref(''), mass=ref(20), api=ref<ApiClient|null>(null), job=ref<any>(null), result=ref<any>(null), manifest=ref<any>(null), forecast=ref<any>(null), evidenceId=ref(''), audit=ref<any[]>([]), importPreview=ref<any>(null)
const formEpoch=ref(0), resource=ref<RegistryKind>('protocols'), exportScope=ref('assets'), editing=ref<any>(null); let poller:number|undefined; let forecastGeneration=0
const mapStatus=ref('')
const sourceContext=ref<any>(null)
const publicData=computed(()=>data.value?.workspace?.mode==='public_data'), forecastLoading=ref(false)
let forecastTimer:ReturnType<typeof setTimeout>|undefined
let contextGeneration=0;let contextTimer:ReturnType<typeof setTimeout>|undefined
const unknownSoil=()=>({composition:null,composition_depth_cm:null,support_m:null,depths:[]})
function queueContext(){const generation=++contextGeneration;clearTimeout(contextTimer);sourceContext.value=null;if(data.value){data.value.soil=unknownSoil();data.value.sources=(data.value.sources||[]).map((s:any)=>({...s,status:'on_request',qc:'unknown',note:'Завантажуємо дані для обраної точки й дати.',retrieved_at:null,observed_at:null,content_sha256:null,data:null}))}if(!api.value||!selectedId.value||!date.value)return;const asset=selectedId.value,day=date.value;contextTimer=setTimeout(async()=>{try{const context=await api.value!.get<any>(`/asset-context?${new URLSearchParams({asset_id:asset,assessment_date:day})}`);if(generation!==contextGeneration||context.asset_id!==asset||context.assessment_date!==day)return;sourceContext.value=context;data.value.soil=context.soil||unknownSoil();const sources=new Map((data.value.sources||[]).map((s:any)=>[s.id,s]));for(const source of context.sources||[])sources.set(source.id,source);data.value.sources=[...sources.values()]}catch(e){if(generation===contextGeneration)message(e)}},200)}
const selected=computed(()=>data.value?.assets?.find((x:any)=>x.id===selectedId.value)||null); const segments=computed(()=>data.value?.segments?.filter((x:any)=>x.asset_id===selectedId.value)||[])
const assets=computed(()=> (data.value?.assets||[]).filter((x:any)=>(!query.value||`${x.id} ${x.name}`.toLowerCase().includes(query.value.toLowerCase()))&&(condition.value==='all'||x.condition===condition.value)))
const observations=computed(()=>data.value?.observations||[]); const series=computed(()=>selectedSeries(result.value,forecast.value,selectedId.value,date.value,Number(mass.value)))
const researchAssessment=computed(()=>{
  const matches=(assessment:any)=>assessment?.asset_id===selectedId.value&&assessment?.assessment_date===date.value&&Number(assessment?.gross_mass_t)===Number(mass.value)
  if(matches(result.value?.assessment)){
    if(result.value?.eligibility==='withdrawn')return null
    return ['research_only','abstained'].includes(result.value.assessment?.research?.status)?result.value.assessment.research:null
  }
  if(matches(forecast.value))return ['research_only','abstained'].includes(forecast.value?.research?.status)?forecast.value.research:null
  return null
})
const pointWeather=computed(()=>series.value.find(row=>typeof row.time==='string'&&['temperature_c','precipitation_mm','moisture_p50'].some(key=>typeof row[key]==='number'&&Number.isFinite(row[key]))))
const labels=computed<Record<string,string>>(()=>({less_adverse:'Менш несприятливі',adverse:'Несприятливі',severe:'Суттєве перезволоження',unknown:publicData.value?'Проїзд не оцінено':'Недостатньо даних'}))
const managementResources=[['assets','Об’єкти'],['segments','Ділянки під’їзду'],['observations','Спостереження'],['protocols','Протоколи'],['models','Моделі'],['envelopes','Транспортні межі'],['constraints','Обмеження'],['tickets','Заявки'],['subscriptions','Підписки'],['inspections','Огляди']] as const
function message(e:any){ error.value=e?.message||'Не вдалося виконати запит' }
function sourceNote(source:any){return sourceSummary(source,sourceContext.value||{},forecast.value)}
async function bootstrap(){const keep={id:selectedId.value,date:date.value,mass:mass.value};busy.value=true;error.value='';try{const r=await fetch('/api/v1/bootstrap',{credentials:'same-origin'}),b=await r.json();if(!r.ok)throw new Error(b.detail);data.value=b;api.value=new ApiClient(b.csrf_token);selectedId.value=b.assets?.some((x:any)=>x.id===keep.id)?keep.id:(b.context?.selected_asset_id||b.assets?.[0]?.id||'');date.value=keep.date||b.context?.assessment_date;mass.value=keep.mass||b.context?.gross_mass_t;queueContext();if(publicData.value)queueForecast()}catch(e){message(e)}finally{busy.value=false}}
async function act(label:string,fn:()=>Promise<any>){if(!api.value)return;busy.value=true;error.value='';try{const r=await fn();notice.value=`${label}: ${r?.status?localized(r.status):'Виконано'}`;return r}catch(e){message(e)}finally{busy.value=false}}
function queueForecast(){clearTimeout(forecastTimer);forecastLoading.value=!!(api.value&&selectedId.value&&date.value);if(forecastLoading.value)forecastTimer=setTimeout(loadForecast,200)}
async function loadForecast(){if(!api.value||!selectedId.value||!date.value)return;const generation=++forecastGeneration;try{const r=await api.value.get<any>(forecastQuery(selectedId.value,date.value,Number(mass.value)));if(generation===forecastGeneration){forecast.value=r;for(const source of r.source_supports||[]){if(!source.id)continue;const row={...source,name:source.product,version:source.model,status:r.series?.length?'available':'unavailable',qc:r.series?.some((x:any)=>x.moisture_p50==null||x.precipitation_mm==null)?'partial':'available',note:'Модельні дані через Open-Meteo. Безкоштовний API — лише для некомерційного прототипу; не вимірювання дорожнього покриття.'};data.value.sources=[...(data.value.sources||[]).filter((x:any)=>x.id!==row.id),row]}}}catch(e){if(generation===forecastGeneration)message(e)}finally{if(generation===forecastGeneration)forecastLoading.value=false}}
function stopPoll(){if(poller)window.clearInterval(poller);poller=undefined}
async function refreshJob(){if(!api.value||!job.value)return;const id=job.value.id;const current=await api.value.get<any>(`/jobs/${id}`);if(job.value?.id!==id)return;job.value=current;if(current.status==='published'){stopPoll();const [r,m]=await Promise.all([api.value.get<any>(`/results/${current.run_id}`),api.value.get(`/results/${current.run_id}/manifest`)]);if(job.value?.id!==id)return;result.value=r;manifest.value=m;forecast.value=r.assessment;notice.value=`Розрахунок: ${localized(r.eligibility==='withdrawn'?'withdrawn':'published')}`}else if(['failed','cancelled'].includes(current.status)){stopPoll();notice.value=`Розрахунок: ${localized(current.status)}`}}
async function analyse(){const r=await act('Розрахунок',()=>api.value!.post('/analyses',{asset_id:selectedId.value,assessment_date:date.value,gross_mass_t:Number(mass.value)},createKey()));if(r){job.value=r;result.value=null;manifest.value=null;stopPoll();await refreshJob();if(job.value?.status==='queued'||job.value?.status==='running')poller=window.setInterval(()=>refreshJob().catch(message),700)}}
async function cancelJob(){if(job.value)await act('Скасування',()=>api.value!.post(`/jobs/${job.value.id}/cancel`,{}));await refreshJob()}
async function withdraw(){if(!job.value)return;const reason=prompt('Підстава відкликання результату');if(reason) {await act('Відкликання',()=>api.value!.post(`/results/${job.value.run_id}/withdraw`,{reason}));await refreshJob()}}
async function inspection(){if(await act('Запит огляду',()=>api.value!.post('/inspections',{asset_id:selectedId.value,status:'requested',reason:'Потрібна польова перевірка під’їзду'})))await bootstrap()}
async function publicExample(){const point=await act('Публічна контрольна точка',()=>api.value!.post('/assets',{name:'Публічна контрольна точка · Норвегія',type:'other',source_ref:'public-reference:manual-control-point:59.66,10.78;not-an-infrastructure-asset',geometry:{type:'Point',coordinates:[10.78,59.66]}}));if(point){selectedId.value=point.id;await bootstrap()}}
async function uploadEvidence(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;evidenceId.value='';const fd=new FormData();fd.append('file',f);const r=await act('Файл доказу',()=>api.value!.upload('/uploads',fd));if(r)evidenceId.value=r.id}
async function observation(){const f=document.querySelector<HTMLFormElement>('#observation');if(!f)return;const x=new FormData(f);const r=await act('Спостереження',()=>api.value!.post('/observations',{asset_id:selectedId.value,observed_at:observationTimeUTC(String(x.get('observed_at'))),procedure:x.get('procedure'),note:x.get('note'),evidence_id:evidenceId.value||undefined}));if(r){evidenceId.value='';f.reset();await bootstrap()}}
async function adjudicate(o:any,decision:string){const reason=prompt('Підстава рішення (обов’язково)');if(reason&&await act('Рецензування',()=>api.value!.post(`/observations/${o.id}/adjudications`,{decision,reason,expected_version:o.version})))await bootstrap()}
async function role(value:string){if(await act('Роль',()=>api.value!.post('/demo/role',{role:value})))await bootstrap()}
async function exportData(format:string){const r=await act('Експорт',()=>api.value!.post('/exports',{format,scope:exportScope.value}));if(r?.download_url)window.open(r.download_url,'_blank','noopener')}
async function offline(){if(!api.value)return;try{const packageData=await api.value.get<any>('/offline-package');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(packageData,null,2)],{type:'application/json'}));a.download='groundsense-offline-package.json';a.click();URL.revokeObjectURL(a.href);notice.value='Офлайн-пакет завантажено: позначений як застарілий.'}catch(e){message(e)}}
async function importData(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;try{const raw=await f.text();const r=await act('Попередній перегляд імпорту',()=>api.value!.post('/imports',{resource:'assets',format:importFormat(f.name),data:raw}));if(r)importPreview.value=r}catch(e){message(e)}}
async function commitImport(){if(!importPreview.value)return;const r=await act('Імпорт',()=>api.value!.post(`/imports/${importPreview.value.id}/commit`,{}));if(r){importPreview.value=null;await bootstrap()}}
function openRecord(item?:any){editing.value=item||null;formEpoch.value++}
async function saveRecord(body:Record<string,unknown>){const r=editing.value?await act('Оновлення',()=>api.value!.patch(`/${resource.value}/${editing.value.id}`,{...body,expected_version:editing.value.version})):await act('Створення',()=>api.value!.post(`/${resource.value}`,body));if(!r)return;await bootstrap();openRecord()}
async function removeRecord(item:any){if(confirm(`Видалити запис ${item.id}? Історія змін збережеться.`)){if(await act('Видалення',()=>api.value!.remove(`/${resource.value}/${item.id}`,{expected_version:item.version})))await bootstrap()}}
function trapTab(e:KeyboardEvent){const controls=[...document.querySelectorAll<HTMLElement>('.drawer button,.drawer input,.drawer select,.drawer textarea')].filter(x=>!x.hasAttribute('disabled'));const first=controls[0],last=controls[controls.length-1];if(e.shiftKey&&document.activeElement===first){last?.focus();e.preventDefault()}else if(!e.shiftKey&&document.activeElement===last){first?.focus();e.preventDefault()}}
watch(drawer,async(open)=>{await nextTick();document.querySelector<HTMLElement>(open?'.drawer button[aria-label="Закрити"]':'.menu')?.focus()})
async function loadAudit(){const r=await act('Аудит',()=>api.value!.get<any>('/audit'));if(r)audit.value=r.items}
watch([selectedId,date],queueContext,{flush:'sync'});watch([selectedId,date,mass],()=>{forecastGeneration++;result.value=null;manifest.value=null;forecast.value=null;notice.value='';stopPoll();job.value=null;if(publicData.value||page.value==='forecast')queueForecast()});watch(page,p=>{if(p==='forecast'&&!forecast.value)queueForecast()});onMounted(bootstrap);onBeforeUnmount(()=>{stopPoll();contextGeneration++;forecastGeneration++;clearTimeout(contextTimer);clearTimeout(forecastTimer)})
</script>
<template><main><div :inert="drawer"><header class="masthead"><strong>GroundSense</strong><nav aria-label="Основна навігація"><button v-for="p in [['map','Карта'],['assets','Об’єкти'],['forecast','Прогноз'],['observations','Спостереження'],['sources','Джерела'],['validation','Перевірки']]" :key="p[0]" :class="{active:page===p[0]}" :aria-current="page===p[0]?'page':undefined" @click="page=p[0] as Page">{{p[1]}}</button></nav><button class="menu" @click="drawer=true">Керування</button></header>
<section class="querybar"><label>Дата оцінки<input v-model="date" type="date"></label><label>Повна маса, т<input v-model.number="mass" type="number" min=".1" step=".1"></label><button class="primary" :disabled="busy||!selectedId" @click="analyse">Розрахувати</button><span class="pill">{{forecast?.mode ? localized(forecast.mode) : 'Дослідницький режим'}}</span><b class="demo">Відкриті дані · дослідний режим</b><span class="muted">{{localized(data?.user?.role||'engineer')}}</span></section>
<p v-if="error" class="alert error" role="alert">{{error}} <button @click="bootstrap">Оновити дані</button></p><p v-if="notice" class="alert" role="status">{{notice}}</p><section v-if="busy&&!data" class="loading">Завантаження…</section><template v-else-if="data">
<section v-if="page==='map'" class="map-layout"><aside class="list-panel"><h2>Об’єкти <small>· {{data.assets.length}}</small></h2><button v-for="(label,key) in labels" :key="key" class="condition-count" @click="condition=condition===key?'all':String(key)"><i :class="key"></i><span>{{label}}</span><b>{{data.assets.filter((a:any)=>a.condition===key).length}}</b></button><input v-model="query" placeholder="Пошук" aria-label="Пошук об’єктів"><select v-model="condition"><option value="all">Усі стани</option><option v-for="(v,k) in labels" :value="k">{{v}}</option></select><button v-if="!data.assets.length" class="asset-row" :disabled="busy" @click="publicExample"><b>Публічний приклад</b><span>Контрольна точка · Норвегія</span><em>Реальні джерела, не об’єкт інфраструктури</em></button><button class="asset-row" v-for="a in assets" :key="a.id" :class="{selected:a.id===selectedId}" @click="selectedId=a.id"><b>{{a.id}}</b><span>{{localized(a.type)}}</span><em>{{labels[a.condition]}}</em></button></aside><div class="map-wrap"><SchematicMap :map="data.map" :assets="assets" :segments="data.segments" :selected-id="selectedId" @select="selectedId=$event" @status="mapStatus=$event"/><div class="map-caption">{{mapStatus||'OpenStreetMap · OpenFreeMap · OpenMapTiles'}}</div></div><aside v-if="selected" class="inspector"><h2>{{selected.id}}</h2><p>{{selected.name}} · {{localized(selected.type)}}</p><p><b>{{labels[selected.condition]}}</b></p><p>{{selected.reason}}</p>
<div v-if="publicData" data-testid="point-conditions"><p><b>Дані природних умов</b></p><p v-if="pointWeather">Ряд прогнозу: {{formatTime(pointWeather.time)}} UTC<br>Температура: {{formatNumber(pointWeather.temperature_c,1)}} °C<br>Опади за годину: {{formatNumber(pointWeather.precipitation_mm,1)}} мм<br>Модельна вологість 0–1 см: {{formatNumber(pointWeather.moisture_p50)}} м³/м³</p><p v-else role="status">{{forecastLoading?'Завантаження модельних даних…':'Числовий прогноз недоступний для цієї точки й дати.'}}</p><p v-if="sourceContext?.terrain?.elevation_m!=null">Висота поверхні: {{formatNumber(sourceContext.terrain.elevation_m,2)}} м (DSM)</p><p v-if="sourceContext?.soil?.composition">Оцінки ґрунту, {{sourceContext.soil.composition_depth_cm?.join('–')}} см:<br>пісок {{formatNumber(sourceContext.soil.composition.sand,1)}}%, пил {{formatNumber(sourceContext.soil.composition.silt,1)}}%, глина {{formatNumber(sourceContext.soil.composition.clay,1)}}%.<br><small>Природний профіль, не дорожній матеріал. Обмеження та QC — у джерелах.</small></p><button @click="page='sources'">Джерела та якість даних</button></div><ResearchAssessment :research="researchAssessment"/>
<p class="warning">Природні умови не описують дорожній матеріал і не підтверджують проїзд.</p><button class="primary wide" @click="inspection">Створити запит огляду</button></aside></section>
<section v-else-if="page==='assets'" class="page"><h1>{{selectedId}} · об’єкт і під’їзди</h1><div class="two"><div class="panel mini-map"><SchematicMap :map="data.map" :assets="data.assets" :segments="segments" :selected-id="selectedId" @select="selectedId=$event"/></div><div class="panel"><h2>Ґрунт / докази</h2><p>Склад ґрунту ({{data.soil.composition_depth_cm?.join('–')}} см): пісок {{formatNumber(data.soil.composition?.sand,1)}}%, пил {{formatNumber(data.soil.composition?.silt,1)}}%, глина {{formatNumber(data.soil.composition?.clay,1)}}%.</p><p>Просторова підтримка: {{formatNumber(data.soil.support_m,0)}} м. Це оцінка природного профілю, не матеріал дорожньої конструкції.</p><table><thead><tr><th>Глибина</th><th>Опис</th><th>Тип оцінки</th></tr></thead><tbody><tr v-for="d in data.soil.depths" :key="d.top_cm"><td>{{d.top_cm}}–{{d.bottom_cm}} см</td><td>{{d.texture}}</td><td>{{localized(d.estimate_kind)}}</td></tr></tbody></table></div></div><div class="panel"><h2>Ділянки під’їзду</h2><table><thead><tr><th>Ділянка</th><th>Довжина</th><th>Покриття</th><th>Конструкція</th><th>Стан огляду</th></tr></thead><tbody><tr v-for="s in segments" :key="s.id"><td>{{s.id}}</td><td>{{s.length_m}} м</td><td>{{localized(s.surface)}}</td><td>{{localized(s.construction)}}</td><td>{{localized(s.inspection_status||'unknown')}}</td></tr></tbody></table></div></section>
<section v-else-if="page==='forecast'" class="page"><h1>{{selectedId}} · прогноз природних умов</h1><p class="subtitle">Зміна дати перераховує прогноз; вона не створює і не змінює дані спостережень.</p><div class="forecast"><div class="panel"><ResearchAssessment :research="researchAssessment"/><h2>Ряд постачальника (не водний баланс)</h2><ForecastChart :series="series"/><p v-if="!series.length" class="muted">{{result?.eligibility==='withdrawn'?'Результат відкликано; траєкторію прибрано.':'Прогноз ще не завантажено.'}}</p><p class="warning">Модельні значення вологості та опадів з указаного джерела; без каліброваного інтервалу невизначеності. Це не прогноз прохідності.</p><table><thead><tr><th>Час (UTC)</th><th>Вологість, м³/м³</th><th>Опади, мм</th></tr></thead><tbody><tr v-for="r in series" :key="r.time"><td>{{formatTime(r.time)}}</td><td>{{formatNumber(r.moisture_p50??r.moisture)}}</td><td>{{formatNumber(r.precipitation_mm,1)}}</td></tr></tbody></table></div><aside class="panel"><h2>Стан розрахунку</h2><p>{{job ? localized(job.status) : 'Не створено'}}</p><button v-if="job&&['queued','running'].includes(job.status)" @click="cancelJob">Скасувати</button><template v-if="result"><p>Повнота: {{localized(result.completeness)}}</p><p>Статус видачі: {{localized(result.eligibility)}}</p><p class="warning">Прохідність не підтверджено. Зовнішні дані не вимірюють несучу здатність дороги.</p><p>Розраховано: {{formatTime(result.assessment.computed_at)}} UTC</p><button @click="withdraw">Відкликати результат</button><details><summary>Маніфест</summary><pre>{{JSON.stringify(manifest,null,2)}}</pre></details></template></aside></div></section>
<section v-else-if="page==='observations'" class="page"><h1>Спостереження та докази</h1><div class="two"><form id="observation" class="panel" @submit.prevent="observation"><h2>Додати спостереження</h2><label>Час спостереження (UTC)<input name="observed_at" type="datetime-local" required></label><label>Процедура<input name="procedure" required></label><label>Примітка<textarea name="note" required></textarea></label><label class="file-picker">Растровий доказ<span>Вибрати фото</span><input type="file" accept="image/*" :disabled="busy" @change="uploadEvidence"></label><small v-if="evidenceId">Файл прикріплено: {{evidenceId}}</small><button class="primary" :disabled="busy">Зберегти</button></form><div class="panel"><h2>Рецензування</h2><div class="record" v-for="o in observations" :key="o.id"><b>{{o.id}}</b><p>Спостережено: {{o.observed_at?formatTime(o.observed_at)+' UTC':'Час не вказано'}}<br><small>Внесено: {{o.entered_at?formatTime(o.entered_at)+' UTC':'Невідомо'}}</small></p><p>{{o.note||o.procedure}}</p><a v-if="o.evidence_id" :href="'/api/v1/uploads/'+encodeURIComponent(o.evidence_id)" target="_blank" rel="noopener"><img class="evidence-thumb" :src="'/api/v1/uploads/'+encodeURIComponent(o.evidence_id)" alt="Прикріплений растровий доказ" loading="lazy">Переглянути доказ</a><small v-else>Без прикріпленого доказу</small><p v-if="o.adjudication">Рішення: {{localized(o.adjudication.decision)}}<br><small>{{o.adjudication.reason}}</small></p><button @click="adjudicate(o,'accepted')">Прийняти</button> <button @click="adjudicate(o,'rejected')">Відхилити</button></div></div></div></section>
<section v-else-if="page==='sources'" class="page"><h1>Джерела даних</h1><div class="panel"><table><thead><tr><th>Джерело</th><th>Продукт</th><th>QC</th><th>Стан</th></tr></thead><tbody><tr v-for="s in data.sources" :key="s.id"><td>{{s.name}}</td><td>{{s.product}} · {{s.version}}</td><td>{{localized(s.qc)}}</td><td>{{localized(s.status)}}<br><small>{{sourceNote(s)}}</small></td></tr></tbody></table><p class="warning">Стан показує фактичну доступність кожного джерела. Метадані каталогу не замінюють вимірювання; відсутні дані не підміняються синтетичними.</p></div></section>
<section v-else class="page"><h1>Перевірки та огляди</h1><div class="two"><div class="panel"><h2>Наукові межі</h2><p>Модель: {{data.models?.[0]?.name}} — {{localized(data.models?.[0]?.status)}}</p><p class="warning">Незалежна валідація та транспортна модель не доступні; затвердження не виконується.</p></div><div class="panel"><h2>Огляди</h2><div v-for="i in data.inspections" :key="i.id" class="record">{{i.id}} · {{localized(i.status)}}<br>{{i.reason}}</div><button @click="inspection">Створити запит огляду</button></div></div><div class="panel"><h2>Покриття функцій · {{data.features.length}}</h2><p class="warning">Наявність сторінки або API не означає виконання виробничих критеріїв. Для кожної функції нижче зазначено фактичний стан.</p><div class="feature-scroll"><table><thead><tr><th>ID</th><th>Функція</th><th>Стан</th><th>Межі реалізації</th></tr></thead><tbody><tr v-for="f in data.features" :key="f.id"><td>{{f.id}}</td><td>{{f.feature}}</td><td>{{f.status}}</td><td>{{f.note}}</td></tr></tbody></table></div></div></section>
</template></div>
<aside v-if="drawer" class="drawer" role="dialog" aria-modal="true" aria-label="Керування" @keydown.esc="drawer=false" @keydown.tab="trapTab">
<header><h2>Керування</h2><button aria-label="Закрити" @click="drawer=false">×</button></header>
<section><h3>Роль прототипу</h3><button v-for="r in ['dispatcher','engineer','field','admin']" :key="r" @click="role(r)">{{localized(r)}}</button></section>
<section><h3>Імпорт та експорт</h3><label>Імпорт об’єктів: CSV / JSON / GeoJSON<input type="file" accept=".csv,.json,.geojson" @change="importData"></label><div v-if="importPreview" class="info">Рядків: {{importPreview.rows}}; помилок: {{importPreview.errors?.length}}<ul v-if="importPreview.errors?.length"><li v-for="x in importPreview.errors" :key="x.row">Рядок {{x.row}}: {{x.message}}</li></ul><button :disabled="importPreview.errors?.length" @click="commitImport">Підтвердити імпорт</button></div><label>Набір для експорту<select v-model="exportScope" aria-label="Набір для експорту"><option v-for="r in managementResources" :key="r[0]" :value="r[0]">{{r[1]}}</option></select></label><button v-for="f in ['csv','geojson','pdf']" :key="f" @click="exportData(f)">Експорт {{f.toUpperCase()}}</button><button @click="offline">Завантажити офлайн-пакет JSON</button></section>
<section><h3>Реєстри робочого простору</h3><label>Реєстр<select v-model="resource" @change="openRecord()"><option v-for="r in managementResources" :key="r[0]" :value="r[0]">{{r[1]}}</option></select></label><table><thead><tr><th>ID</th><th>Назва / стан</th><th>Дії</th></tr></thead><tbody><tr v-for="x in data?.[resource]||[]" :key="x.id"><td>{{x.id}}</td><td>{{x.name||x.title||localized(x.status)||'—'}}</td><td><button :disabled="busy" @click="openRecord(x)">Редагувати</button><button v-if="data?.user?.role==='admin'" :disabled="busy" @click="removeRecord(x)">Видалити</button></td></tr><tr v-if="!(data?.[resource]||[]).length"><td colspan="3" class="muted">У цьому реєстрі поки немає записів.</td></tr></tbody></table><h4>{{editing?'Редагування запису':'Новий запис'}}</h4><RegistryForm :key="`${resource}:${editing?.id||'new'}:${formEpoch}`" :kind="resource" :record="editing" :assets="data?.assets||[]" :segments="data?.segments||[]" :busy="busy" :public-data="data?.workspace?.mode==='public_data'" @submit="saveRecord" @cancel="openRecord()"/><p class="muted">Редактор змінює лише реєстр вашого робочого простору. Видалення доступне адміністратору; історія змін зберігається.</p></section>
<section><h3>Аудит</h3><button @click="loadAudit">Оновити журнал</button><div v-for="x in audit" :key="x.at" class="record">{{formatTime(x.at)}} UTC · {{localized(x.role)}} · {{localized(x.action)}} · {{x.target}}</div></section>
</aside></main></template>
